import React from "react";
import { Nav } from "react-bootstrap";
import { LinkContainer } from "react-router-bootstrap";

function CheckoutSteps({ step1, step2, step3, step4 }) {
  return (
    <Nav className="justify-content-center mb-4">
      <Nav.Item>
        {step1 ? (
          <LinkContainer to="/login">
            <Nav.Link>Σύνδεση</Nav.Link>
            {/* <Nav.Link>Login</Nav.Link> */}
          </LinkContainer>
        ) : (
          <Nav.Link disabled>Σύνδεση</Nav.Link>
          //   <Nav.Link disabled>Login</Nav.Link>
        )}
      </Nav.Item>

      <Nav.Item>
        {step2 ? (
          <LinkContainer to="/shipping">
            {/* <Nav.Link>Shipping</Nav.Link> */}
            <Nav.Link>Αποστολή</Nav.Link>
          </LinkContainer>
        ) : (
          // <Nav.Link disabled>Shipping</Nav.Link>
          <Nav.Link disabled>Αποστολή</Nav.Link>
        )}
      </Nav.Item>

      <Nav.Item>
        {step3 ? (
          <LinkContainer to="/payment">
            <Nav.Link>Πληρωμή</Nav.Link>
            {/* <Nav.Link>Payment</Nav.Link> */}
          </LinkContainer>
        ) : (
          <Nav.Link disabled>Πληρωμή</Nav.Link>
          // <Nav.Link disabled>Payment</Nav.Link>
        )}
      </Nav.Item>

      <Nav.Item>
        {step4 ? (
          <LinkContainer to="/placeorder">
            <Nav.Link>Ολοκλήρωση Παραγγελίας</Nav.Link>
            {/* <Nav.Link>Place Order</Nav.Link> */}
          </LinkContainer>
        ) : (
          <Nav.Link disabled>Ολοκλήρωση Παραγγελίας</Nav.Link>
          // <Nav.Link disabled>Place Order</Nav.Link>
        )}
      </Nav.Item>
    </Nav>
  );
}

export default CheckoutSteps;
