import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { Navbar, Nav, Container, NavDropdown } from "react-bootstrap";
import { LinkContainer } from "react-router-bootstrap";
import SearchBox from "./SearchBox";
import { logout } from "../actions/userActions";

import ButtonGroup from "react-bootstrap/ButtonGroup";
import Dropdown from "react-bootstrap/Dropdown";
import DropdownButton from "react-bootstrap/DropdownButton";

function Header() {
  const userLogin = useSelector((state) => state.userLogin);
  const { userInfo } = userLogin;

  const dispatch = useDispatch();

  const logoutHandler = () => {
    dispatch(logout());
  };

  return (
    <header>
      <Navbar
        bg="light"
        variant="light"
        expand="lg"
        className="py-0 border-0"
        collapseOnSelect
      >
        <Container>
          <LinkContainer to="/">
            <Navbar.Brand className="py-0">
              <img
                className="mr-3"
                style={{ transform: "scale(1.55)" }}
                src={`${process.env.PUBLIC_URL}/images/oblako.png`}
                width={150}
                alt="Oblako Logo"
              />
            </Navbar.Brand>
          </LinkContainer>

          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            <SearchBox />
            <Nav className="ml-auto">
              <DropdownButton as={ButtonGroup} variant="secondary" title="TODO">
                {["ΕΛ", "EN"].map((lang, i) => (
                  <Dropdown.Item
                    eventKey={i}
                    active={lang === "ΕΛ" ? true : undefined}
                  >
                    {lang}
                  </Dropdown.Item>
                ))}
              </DropdownButton>

              <LinkContainer to="/cart">
                <Nav.Link>
                  <i className="fas fa-shopping-cart mr-2 fa-lg"></i> ΚΑΛΑΘΙ
                  {/* Cart */}
                </Nav.Link>
              </LinkContainer>

              {userInfo ? (
                <NavDropdown title={userInfo.name} id="username">
                  <LinkContainer to="/profile">
                    <NavDropdown.Item>Προφίλ</NavDropdown.Item>
                    {/* <NavDropdown.Item>Profile</NavDropdown.Item> */}
                  </LinkContainer>

                  <NavDropdown.Item onClick={logoutHandler}>
                    Αποσύνδεση
                  </NavDropdown.Item>
                  {/* <NavDropdown.Item onClick={logoutHandler}>
                    Logout
                  </NavDropdown.Item> */}
                </NavDropdown>
              ) : (
                <LinkContainer to="/login">
                  <Nav.Link>
                    <i className="fas fa-user mr-2 fa-lg"></i>ΣΥΝΔΕΣΗ
                    {/* <i className="fas fa-user mr-2 fa-lg"></i>Login */}
                  </Nav.Link>
                </LinkContainer>
              )}

              {userInfo && userInfo.isAdmin && (
                <NavDropdown title="Admin" id="adminmenue">
                  <LinkContainer to="/admin/userlist">
                    <NavDropdown.Item>Χρήστες</NavDropdown.Item>
                    {/* <NavDropdown.Item>Users</NavDropdown.Item> */}
                  </LinkContainer>

                  <LinkContainer to="/admin/productlist">
                    <NavDropdown.Item>Προϊόντα</NavDropdown.Item>
                    {/* <NavDropdown.Item>Products</NavDropdown.Item> */}
                  </LinkContainer>

                  <LinkContainer to="/admin/orderlist">
                    <NavDropdown.Item>Παραγγελίες</NavDropdown.Item>
                    {/* <NavDropdown.Item>Orders</NavDropdown.Item> */}
                  </LinkContainer>
                </NavDropdown>
              )}
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>
    </header>
  );
}

export default Header;
