import { useState } from "react";
import Button from "react-bootstrap/Button";
import Modal from "react-bootstrap/Modal";
import { useEffect } from "react";

function AgeCheckModal() {
  const [show, setShow] = useState(false);

  const handleClose = () => setShow(false);
  const handleCancel = () => (window.location.href = "https://www.google.com");
  const handleShow = () => setShow(true);

  useEffect(() => {
    handleShow();
  }, []);

  return (
    <>
      <Modal
        show={show}
        onHide={handleClose}
        backdrop="static"
        keyboard={false}
      >
        <Modal.Header>
          {/* <Modal.Title>Are you old enough?</Modal.Title> */}
          <Modal.Title>Είσαι ενήλικας;</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {/* Our offer is only for you if you are of legal age. Please confirm that you are 18 years old or older to proceed. */}
          Η προσφορές μας είναι διαθέσιμες μόνο για ενήλικες. Παρακαλώ
          επιβεβαιώστε ότι είστε 18 ετών ή μεγαλύτεροι για να συνεχίσετε.
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCancel}>
            {/* Cancel */}
            ΕΙΜΑΙ ΑΝΗΛΙΚΟΣ
          </Button>
          <Button variant="primary" onClick={handleClose}>
            {/* Yes, I am of legal age */}
            ΝΑΙ, ΕΙΜΑΙ ΕΝΗΛΙΚΑΣ
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

export default AgeCheckModal;
